def vertex_connectivity(edges, n=16):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    def bfs(s, t, parent, capacity, adj_dir):
        visited = set([s])
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v in adj_dir[u]:
                if v not in visited and capacity[u][v] > 0:
                    visited.add(v)
                    parent[v] = u
                    queue.append(v)
                    if v == t:
                        return True
        return False

    def max_flow(s, t, capacity, adj_dir):
        parent = {}
        max_flow = 0
        while bfs(s, t, parent, capacity, adj_dir):
            path_flow = float("Inf")
            s_curr = t
            while s_curr != s:
                path_flow = min(path_flow, capacity[parent[s_curr]][s_curr])
                s_curr = parent[s_curr]
            max_flow += path_flow
            v = t
            while v != s:
                u = parent[v]
                capacity[u][v] -= path_flow
                capacity[v][u] += path_flow
                v = parent[v]
        return max_flow

    min_conn = n - 1
    for i in range(n):
        for j in range(i+1, n):
            if j not in adj[i]:
                # Build flow network
                # Split each vertex v into v_in and v_out
                capacity = {k: {} for k in range(2*n)}
                adj_dir = {k: set() for k in range(2*n)}

                def add_edge(u, v, cap):
                    capacity[u][v] = cap
                    capacity[v][u] = 0
                    adj_dir[u].add(v)
                    adj_dir[v].add(u)

                for v in range(n):
                    add_edge(2*v, 2*v+1, 1)

                for u in range(n):
                    for v in adj[u]:
                        add_edge(2*u+1, 2*v, float('inf'))

                conn = max_flow(2*i+1, 2*j, capacity, adj_dir)
                min_conn = min(min_conn, conn)
    return min_conn

